package it.frociart.app;
import java.nio.file.*;import java.nio.charset.*;import java.util.*;
public final class ExpressionCompatTests {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static String dec(String b){return new String(Base64.getDecoder().decode(b),StandardCharsets.UTF_8);}
 static FlowEngine.Runner run(String code){FlowEngine.Runner r=new FlowEngine.Runner(FlowPseudocode.decode(code));for(int i=0;i<1000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++)r.step();return r;}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);List<String> conversions=new ArrayList<>();for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.US_ASCII)){String[] v=line.split("\t",-1);String original=dec(v[2]),expr=original,expected=dec(v[3]);FlowEngine.Value actual=null;boolean failed=false;try{if(v[0].equals("convert"))expr=FlowgorithmImport.convertExpression(expr);actual=FlowEngine.evaluate(expr,null);}catch(IllegalArgumentException e){failed=true;}check(failed==v[1].equals("error"),original+" error="+failed);if(failed)continue;check(v[1].equals("text")?actual.isText():v[1].equals("bool")?actual.isBoolean():actual.isNumber(),original+" type");check(actual.format().equals(expected),original+" result="+actual.format()+" expected="+expected);if(v[0].equals("convert"))conversions.add(v[2]+"\t"+Base64.getEncoder().encodeToString(expr.getBytes(StandardCharsets.UTF_8)));
  FlowModel.Document d=FlowPseudocode.decode("risultato = "+expr+"\nSTAMPA risultato");for(int i=0;i<2;i++){FlowEngine.Runner runtime=new FlowEngine.Runner(d);for(int n=0;n<15&&runtime.state!=FlowEngine.State.COMPLETED&&runtime.state!=FlowEngine.State.ERROR;n++)runtime.step();check(runtime.state==FlowEngine.State.COMPLETED&&runtime.output.equals(Arrays.asList(expected)),"graph/codec execution "+original);d=FlowCodec.decode(FlowCodec.encode(FlowPseudocode.decode(FlowPseudocode.encode(d)))) ;}
 }
 Map<String,FlowEngine.Value> vars=new HashMap<>();vars.put("mod",FlowEngine.Value.number(7));vars.put("model",FlowEngine.Value.number(11));vars.put("mod5",FlowEngine.Value.number(13));vars.put("large",FlowEngine.Value.text(String.join("",Collections.nCopies(32768,"x"))));
 for(String[] pair:new String[][]{{"mod + 1","8"},{"mod mod 5","2"},{"model + mod5","24"},{"2 * mod","14"}})check(FlowEngine.evaluate(pair[0],vars).format().equals(pair[1]),"Legacy identifier "+pair[0]);
 check(FlowEngine.evaluate("large & \"\"",vars).format().length()==32768,"concat exact string boundary");boolean overflow=false;try{FlowEngine.evaluate("large & 1",vars);}catch(IllegalArgumentException e){overflow=true;}check(overflow,"concat overflow");
 check(FlowEngine.evaluate("-2^2",null).format().equals("-4")&&FlowEngine.evaluate("2^3^2",null).format().equals("512"),"Legacy power unchanged");check(new HashSet<>(FlowEngine.referencedVariables("mod mod model & mod5")).equals(new HashSet<>(Arrays.asList("mod","model","mod5"))),"Contextual mod references");
 String functions="FUNZIONE mod(x: REALE) -> REALE r\nr = x × 2\nFINE FUNZIONE\nSTAMPA mod(3) & mod(4)\nSTAMPA 17 mod mod(2)";FlowModel.Document fdoc=FlowPseudocode.decode(functions);String converted=FlowgorithmImport.convertExpression("mod(3) & mod(4)",FlowFunctions.catalog(fdoc));check(converted.contains("mod(3)")&&converted.contains("mod(4)"),"Passive project function conversion");FlowEngine.Runner runtime=run(functions);check(runtime.state==FlowEngine.State.COMPLETED&&runtime.output.equals(Arrays.asList("68","1")),"User function named mod and concat order");
 for(String code:new String[]{"STAMPA 1 & 2","DICHIARA x: TESTO\nx = 1 & 2\nSTAMPA x","STAMPA \"Resto: \" & 2","STAMPA 17 mod 5","STAMPA 3 ≤ 5"}){FlowgorithmExport.Result export=FlowgorithmExport.analyze(FlowPseudocode.decode(code));check(export.canExport(),"FPRG accepts "+code);FlowEngine.Runner copy=new FlowEngine.Runner(FlowgorithmImport.decode(export.xml));while(copy.state!=FlowEngine.State.COMPLETED&&copy.state!=FlowEngine.State.ERROR)copy.step();check(copy.state==FlowEngine.State.COMPLETED&&copy.output.equals(run(code).output),"FPRG scalar roundtrip");}
 for(String bad:new String[]{String.join("",Collections.nCopies(49,"("))+"1"+String.join("",Collections.nCopies(49,")")),String.join("",Collections.nCopies(8193,"1")),String.join("+",Collections.nCopies(600,"1"))}){boolean rejected=false;try{FlowgorithmImport.convertExpression(bad);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Bounded conversion");}
 check(conversions.equals(Files.readAllLines(root.resolve("converted-pc.tsv"),StandardCharsets.US_ASCII)),"Byte-identical passive conversions PC/Android");System.out.println("EXPRESSION_COMPAT_ANDROID PASS checks="+checks);
 }
}
